#include <iostream>
#include <vector>
#include <string>
using namespace std;

void bitAdd(vector<long long>& t, long long i, long long x) {
    long long n = (long long)t.size() - 1;
    for (; i <= n; i += i & -i) t[i] += x;
}

long long bitSum(const vector<long long>& t, long long i) {
    long long s = 0;
    for (; i > 0; i -= i & -i) s += t[i];
    return s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<vector<long long>> ch(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> ch[i][j];
        }
    }

    long long m = 2 * n;
    vector<long long> partner(m + 1, 0), t(m + 1, 0);
    for (const vector<long long>& c : ch) {
        partner[c[0]] = c[1];
        partner[c[1]] = c[0];
    }
    long long total = 0;
    for (long long x = 1; x <= m; x++) {
        long long y = partner[x];
        if (y > x) {
            bitAdd(t, x, 1);
        } else {
            bitAdd(t, y, -1);
            total += bitSum(t, x) - bitSum(t, y);
        }
    }
    cout << total << "\n";

    return 0;
}

