import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static void bitAdd(long[] t, int i, long x) {
        int n = t.length - 1;
        for (; i <= n; i += i & -i) t[i] += x;
    }

    static long bitSum(long[] t, int i) {
        long s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] ch = new long[(int) n][2];
        for (int i = 0; i < ch.length; i++) {
            for (int j = 0; j < ch[i].length; j++) {
                ch[i][j] = Long.parseLong(next());
            }
        }

        int m = 2 * (int) n;
        int[] partner = new int[m + 1];
        long[] t = new long[m + 1];
        for (int i = 0; i < n; i++) {
            partner[(int) ch[i][0]] = (int) ch[i][1];
            partner[(int) ch[i][1]] = (int) ch[i][0];
        }
        long total = 0;
        for (int x = 1; x <= m; x++) {
            int y = partner[x];
            if (y > x) {
                bitAdd(t, x, 1);
            } else {
                bitAdd(t, y, -1);
                total += bitSum(t, x) - bitSum(t, y);
            }
        }
        System.out.println(total);
    }
}
